# shellcheck shell=bash
# Template spring-boot: generated by start.spring.io (Spring's official generator).
# Database and server settings are environment variables in devctl.env (0600, git-ignored).

readonly TPL_INITIALIZR=https://start.spring.io/starter.zip

tpl_create() { # PATH NAME ENGINE
  local path=$1 name=$2 engine=$3 dir deps="web,validation,devtools" pkg
  case $engine in mysql) deps+=",data-jpa,mysql" ;; postgres) deps+=",data-jpa,postgresql" ;; esac
  pkg="dev.${name//-/}"
  if ((DEVCTL_DRY_RUN)); then
    ui_plan "download a Spring Boot project from $TPL_INITIALIZR (maven, java $(config_get runtime.java_default), $deps), unpack into $path"
    return 0
  fi
  make_temp_dir dir
  ui_step "Generating the project with start.spring.io"
  curl -fsS --proto '=https' --max-time 120 -o "$dir/project.zip" "$TPL_INITIALIZR" \
    -d type=maven-project -d language=java -d "javaVersion=$(config_get runtime.java_default)" \
    -d "groupId=dev" -d "artifactId=$name" -d "name=$name" -d "packageName=$pkg" \
    -d "dependencies=$deps" || die "$EX_EXTERNAL" "start.spring.io did not answer"
  mkdir -p -- "$path"
  unzip -q -- "$dir/project.zip" -d "$path" || die "$EX_EXTERNAL" "could not unpack the project"
  chmod +x -- "$path/mvnw"
  printf '%s\n' "$(config_get runtime.java_default)" >"$path/.java-version"
  printf '\n# devctl: local settings with passwords\ndevctl.env\n' >>"$path/.gitignore"
}

tpl_configure() { # PATH NAME ENGINE DB_PORT DB USER PASS
  local path=$1 file="$1/devctl.env" url=""
  case $3 in
    mysql) url="jdbc:mysql://127.0.0.1:$4/$5" ;;
    postgres) url="jdbc:postgresql://127.0.0.1:$4/$5" ;;
  esac
  : >"$file"
  chmod 600 -- "$file"
  if [[ -n $url ]]; then
    env_set "$file" SPRING_DATASOURCE_URL "$url"
    env_set "$file" SPRING_DATASOURCE_USERNAME "$6"
    env_set "$file" SPRING_DATASOURCE_PASSWORD "$7"
    # An existing database (shared with another site) must not be changed by Hibernate.
    env_set "$file" SPRING_JPA_HIBERNATE_DDL_AUTO "$([[ -n ${SITE_EXISTING_DB:-} ]] && echo none || echo update)"
  fi
}

# Run the app on its own local port; Caddy serves it at https://NAME.test.
tpl_dev() { # PATH NAME PORT
  local path=$1
  local -a envs=(SERVER_ADDRESS=127.0.0.1 "SERVER_PORT=$3" SERVER_FORWARD_HEADERS_STRATEGY=framework)
  local line
  if [[ -f $path/devctl.env ]]; then
    while IFS= read -r line; do
      [[ $line =~ ^[A-Z][A-Z0-9_]*=[A-Za-z0-9._:/@+-]*$ ]] && envs+=("$line")
    done <"$path/devctl.env"
  fi
  (cd -- "$path" && env "${envs[@]}" "$(site__java_home "$path")/bin/java" -version >/dev/null 2>&1) ||
    die "$EX_PRECONDITION" "Java $(site__java_version "$path") JDK not found (devctl runtime setup java)"
  local -a run=(./mvnw -q spring-boot:run)
  if [[ ! -x $path/mvnw && -x $path/gradlew ]]; then run=(./gradlew -q bootRun); fi
  [[ -x $path/${run[0]#./} ]] || die "$EX_PRECONDITION" "no Maven or Gradle wrapper (mvnw / gradlew) in $path"
  (cd -- "$path" && env "${envs[@]}" JAVA_HOME="$(site__java_home "$path")" "${run[@]}")
}
